/// Sends users without a saved token to [redirectTo].
///
/// ```dart
/// GetPage(
///   name: Routes.PROFILE,
///   page: () => const ProfileView(),
///   middlewares: [AuthMiddleware(redirectTo: Routes.LOGIN)],
/// )
