    'lib/core/services/localization_service.dart': r'''import 'dart:ui';

import 'package:get/get.dart';

import 'storage_service.dart';

/// Saves and restores the app language.
class LocalizationService {
  static const fallbackLocale = Locale('en');

  /// Languages the app supports (must match `MyLocal.keys`).
  static const supportedLocales = [Locale('en'), Locale('ar')];

  static StorageService get _storage => Get.find<StorageService>();

  /// The saved language, or the device language when it is supported.
  static Locale get locale {
    final saved = _storage.getString(StorageKeys.languageCode);
    if (saved != null) return Locale(saved);
    final device = Get.deviceLocale;
    final supported =
        supportedLocales.any((l) => l.languageCode == device?.languageCode);
    return supported ? Locale(device!.languageCode) : fallbackLocale;
  }

  static Future<void> changeLocale(String languageCode) async {
    await Get.updateLocale(Locale(languageCode));
    await _storage.setString(StorageKeys.languageCode, languageCode);
  }
}
''',
    'lib/core/services/storage_service.dart': r'''import 'package:get/get.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// Keys saved in local storage.
abstract class StorageKeys {
  static const token = 'token';
  static const themeMode = 'theme_mode';
  static const languageCode = 'language_code';
}

/// Local key-value storage (SharedPreferences). Registered in `main()`
/// before the app starts, so it is always available with `Get.find`.
class StorageService extends GetxService {
  late SharedPreferences _prefs;

  Future<StorageService> init() async {
    _prefs = await SharedPreferences.getInstance();
    return this;
  }

  String? getString(String key) => _prefs.getString(key);

  Future<bool> setString(String key, String value) =>
      _prefs.setString(key, value);

  Future<bool> remove(String key) => _prefs.remove(key);

  String? get token => getString(StorageKeys.token);

  Future<void> saveToken(String? token) async {
    if (token == null) {
      await remove(StorageKeys.token);
    } else {
      await setString(StorageKeys.token, token);
    }
  }
}
''',
    'lib/core/services/theme_service.dart':
        r'''import 'package:flutter/material.dart';
import 'package:get/get.dart';

import 'storage_service.dart';

/// Saves and restores the theme mode (light / dark / system).
class ThemeService {
  static StorageService get _storage => Get.find<StorageService>();

  static ThemeMode get themeMode {
    return switch (_storage.getString(StorageKeys.themeMode)) {
      'light' => ThemeMode.light,
      'dark' => ThemeMode.dark,
      _ => ThemeMode.system,
    };
  }

  static Future<void> changeThemeMode(ThemeMode mode) async {
    Get.changeThemeMode(mode);
    await _storage.setString(StorageKeys.themeMode, mode.name);
  }
}
