    'lib/core/services/localization_service.dart': r'''import 'dart:ui';

import 'package:thunder_template/helper/translations/tr_extension.dart';

import 'storage_service.dart';

/// Saves and restores the app language.
class LocalizationService {
  static const fallbackLocale = Locale('en');

  /// Languages the app supports (must match `MyLocal.keys`).
  static const supportedLocales = [Locale('en'), Locale('ar')];

  /// The saved language, or the device language when it is supported.
  static Locale savedLocale(StorageService storage) {
    final saved = storage.getString(StorageKeys.languageCode);
    final device = PlatformDispatcher.instance.locale.languageCode;
    final code = saved ??
        (supportedLocales.any((l) => l.languageCode == device)
            ? device
            : fallbackLocale.languageCode);
    AppTranslations.languageCode = code;
    return Locale(code);
  }

  static Future<Locale> changeLocale(
      StorageService storage, String languageCode) async {
    AppTranslations.languageCode = languageCode;
    await storage.setString(StorageKeys.languageCode, languageCode);
    return Locale(languageCode);
  }
}
''',
    'lib/core/services/storage_service.dart':
        r'''import 'package:shared_preferences/shared_preferences.dart';

/// Keys saved in local storage.
abstract class StorageKeys {
  static const token = 'token';
  static const themeMode = 'theme_mode';
  static const languageCode = 'language_code';
}

/// Local key-value storage (SharedPreferences). Registered in
/// `setupDependencies()` before the app starts: `sl<StorageService>()`.
class StorageService {
  late SharedPreferences _prefs;

  Future<StorageService> init() async {
    _prefs = await SharedPreferences.getInstance();
    return this;
  }

  String? getString(String key) => _prefs.getString(key);

  Future<bool> setString(String key, String value) =>
      _prefs.setString(key, value);

  Future<bool> remove(String key) => _prefs.remove(key);

  String? get token => getString(StorageKeys.token);

  Future<void> saveToken(String? token) async {
    if (token == null) {
      await remove(StorageKeys.token);
    } else {
      await setString(StorageKeys.token, token);
    }
  }
}
''',
    'lib/core/services/theme_service.dart':
        r'''import 'package:flutter/material.dart';

import 'storage_service.dart';

/// Saves and restores the theme mode (light / dark / system).
class ThemeService {
  static ThemeMode savedThemeMode(StorageService storage) {
    return switch (storage.getString(StorageKeys.themeMode)) {
      'light' => ThemeMode.light,
      'dark' => ThemeMode.dark,
      _ => ThemeMode.system,
    };
  }

  static Future<void> saveThemeMode(
      StorageService storage, ThemeMode mode) async {
    await storage.setString(StorageKeys.themeMode, mode.name);
  }
}
