    'lib/helper/translations/tr_extension.dart':
        r'''import 'package:flutter/widgets.dart';

import 'local.dart';

/// Current language used by [TranslateString.tr].
class AppTranslations {
  static String languageCode = 'en';

  static final Map<String, Map<String, String>> _keys = MyLocal().keys;

  /// Rebuilds every widget under [context] so `.tr` texts use the new language.
  static void refreshApp(BuildContext context) {
    void rebuild(Element element) {
      element.markNeedsBuild();
      element.visitChildren(rebuild);
    }

    (context as Element).visitChildren(rebuild);
  }

  static String translate(String key) =>
      _keys[languageCode]?[key] ?? _keys['en']?[key] ?? key;
}

/// `Text(StringsConstants.home.tr)` shows the text in the current language.
extension TranslateString on String {
  String get tr => AppTranslations.translate(this);
}
''',
    'lib/helper/widgets/api_widgets/api_state_widget.dart':
        r'''import 'package:flutter/material.dart';

import '../../../core/networking/api_result.dart';
import '../../../core/networking/enums_networking.dart';
import '../../constants/strings_constants.dart';
import '../../translations/tr_extension.dart';
import '../custom_widgets/custom_button.dart';
import '../custom_widgets/custom_text.dart';

/// Shows loading / error / empty states for an [ApiResult] and [child] when
/// the data is ready.
class ApiStateWidget extends StatelessWidget {
  const ApiStateWidget({
    super.key,
    required this.apiResult,
    required this.child,
    this.onRetry,
  });

  final ApiResult apiResult;
  final Widget child;
  final VoidCallback? onRetry;

  @override
  Widget build(BuildContext context) {
    return switch (apiResult.apiCallStatus) {
      ApiCallStatus.holding ||
      ApiCallStatus.loading =>
        const Center(child: CircularProgressIndicator()),
      ApiCallStatus.error => Center(
          child: Padding(
            padding: const EdgeInsets.all(24),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                CustomText(
                  txt: apiResult.message ??
                      StringsConstants.somethingWentWrong.tr,
                  textAlign: TextAlign.center,
                ),
                if (onRetry != null) ...[
                  const SizedBox(height: 16),
                  CustomButton(
                      text: StringsConstants.retry.tr, onPressed: onRetry),
                ],
              ],
            ),
          ),
        ),
      ApiCallStatus.empty =>
        Center(child: CustomText(txt: StringsConstants.noData.tr)),
      ApiCallStatus.success => child,
    };
  }
}
''',
    'lib/helper/widgets/custom_widgets/custom_button.dart':
        r'''import 'package:flutter/material.dart';

import 'custom_text.dart';

/// Primary button used across the app. Shows a spinner while [isLoading].
class CustomButton extends StatelessWidget {
  const CustomButton({
    super.key,
    required this.text,
    required this.onPressed,
    this.isLoading = false,
  });

  final String text;
  final VoidCallback? onPressed;
  final bool isLoading;

  @override
  Widget build(BuildContext context) {
    return FilledButton(
      onPressed: isLoading ? null : onPressed,
      child: isLoading
          ? const SizedBox.square(
              dimension: 20, child: CircularProgressIndicator(strokeWidth: 2))
          : CustomText(txt: text),
    );
  }
}
